import{_ as s,c as o,o as r,j as n,Y as a,t as i}from"./chunks/framework.BNTND4LZ.js";const f=JSON.parse('{"title":"ipset | x-cmd man (ip man8) | ipset --- administration tool for IP sets","titleTemplate":false,"description":"x-cmd man (ip man8 Manual Page) | ipset - ipset --- administration tool for IP sets","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"ipset | x-cmd man (ip man8) | ipset --- administration tool for IP sets"}],["meta",{"name":"og:description","content":"x-cmd man (ip man8 Manual Page) | ipset - ipset --- administration tool for IP sets"}]]},"headers":[],"params":{"isMan":true,"man":"ipset","category":"ip man8","desc":"ipset --- administration tool for IP sets"},"relativePath":"ip/man8/ipset.md","filePath":"ip/man8/[man].md"}'),m={name:"ip/man8/ipset.md"},p={class:"visually-hidden"};function d(t,e,h,g,l,c){return r(),o("div",null,[n("h1",p,i(t.$params.man),1),e[0]||(e[0]=a(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>ipset --- administration tool for IP sets</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>ipset</strong> [ <em>OPTIONS</em> ] <em>COMMAND</em> [ <em>COMMAND-OPTIONS</em> ]</p><p>COMMANDS := { <strong>create</strong> | <strong>add</strong> | <strong>del</strong> | <strong>test</strong> | <strong>destroy</strong> | <strong>list</strong> | <strong>save</strong> | <strong>restore</strong> | <strong>flush</strong> | <strong>rename</strong> | <strong>swap</strong> | <strong>help</strong> | <strong>version</strong> | <strong>-</strong> }</p><p><em>OPTIONS</em> := { <strong>-exist</strong> | <strong>-output</strong> { <strong>plain</strong> | <strong>save</strong> | <strong>xml</strong> } | <strong>-quiet</strong> | <strong>-resolve</strong> | <strong>-sorted</strong> | <strong>-name</strong> | <strong>-terse</strong> | <strong>-file</strong> <em>filename</em> }</p><p><strong>ipset</strong> <strong>create</strong> <em>SETNAME</em> <em>TYPENAME</em> [ <em>CREATE-OPTIONS</em> ]</p><p><strong>ipset</strong> <strong>add</strong> <em>SETNAME</em> <em>ADD-ENTRY</em> [ <em>ADD-OPTIONS</em> ]</p><p><strong>ipset</strong> <strong>del</strong> <em>SETNAME</em> <em>DEL-ENTRY</em> [ <em>DEL-OPTIONS</em> ]</p><p><strong>ipset</strong> <strong>test</strong> <em>SETNAME</em> <em>TEST-ENTRY</em> [ <em>TEST-OPTIONS</em> ]</p><p><strong>ipset</strong> <strong>destroy</strong> [ <em>SETNAME</em> ]</p><p><strong>ipset</strong> <strong>list</strong> [ <em>SETNAME</em> ]</p><p><strong>ipset</strong> <strong>save</strong> [ <em>SETNAME</em> ]</p><p><strong>ipset</strong> <strong>restore</strong></p><p><strong>ipset</strong> <strong>flush</strong> [ <em>SETNAME</em> ]</p><p><strong>ipset</strong> <strong>rename</strong> <em>SETNAME-FROM</em> <em>SETNAME-TO</em></p><p><strong>ipset</strong> <strong>swap</strong> <em>SETNAME-FROM</em> <em>SETNAME-TO</em></p><p><strong>ipset</strong> <strong>help</strong> [ <em>TYPENAME</em> ]</p><p><strong>ipset</strong> <strong>version</strong></p><p><strong>ipset</strong> <strong>-</strong></p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p><strong>ipset</strong> is used to set up, maintain and inspect so called IP sets in the Linux kernel. Depending on the type of the set, an IP set may store IP(v4/v6) addresses, (TCP/UDP) port numbers, IP and MAC address pairs, IP address and port number pairs, etc. See the set type definitions below.</p><p><strong>Iptables</strong> matches and targets referring to sets create references, which protect the given sets in the kernel. A set cannot be destroyed while there is a single reference pointing to it.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>The options that are recognized by <strong>ipset</strong> can be divided into several different groups.</p><h3 id="commands" tabindex="-1">COMMANDS <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;COMMANDS&quot;">​</a></h3><p>These options specify the desired action to perform. Only one of them can be specified on the command line unless otherwise specified below. For all the long versions of the command names, you need to use only enough letters to ensure that <strong>ipset</strong> can differentiate it from all other commands. The <strong>ipset</strong> parser follows the order here when looking for the shortest match in the long command names.</p><dl><dt><strong>n</strong>, <strong>create</strong> <em>SETNAME</em> <em>TYPENAME</em> [ <em>CREATE-OPTIONS</em> ]</dt><dd>Create a set identified with setname and specified type. The type may require type specific options. If the <strong>-exist</strong> option is specified, <strong>ipset</strong> ignores the error otherwise raised when the same set (setname and create parameters are identical) already exists.</dd><dt><strong>add</strong> <em>SETNAME</em> <em>ADD-ENTRY</em> [ <em>ADD-OPTIONS</em> ]</dt><dd>Add a given entry to the set. If the <strong>-exist</strong> option is specified, <strong>ipset</strong> ignores if the entry already added to the set.</dd><dt><strong>del</strong> <em>SETNAME</em> <em>DEL-ENTRY</em> [ <em>DEL-OPTIONS</em> ]</dt><dd>Delete an entry from a set. If the <strong>-exist</strong> option is specified and the entry is not in the set (maybe already expired), then the command is ignored.</dd><dt><strong>test</strong> <em>SETNAME</em> <em>TEST-ENTRY</em> [ <em>TEST-OPTIONS</em> ]</dt><dd>Test whether an entry is in a set or not. Exit status number is zero if the tested entry is in the set and nonzero if it is missing from the set.</dd><dt><strong>x</strong>, <strong>destroy</strong> [ <em>SETNAME</em> ]</dt><dd>Destroy the specified set or all the sets if none is given.</dd></dl><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">If</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> has</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> got</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reference</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nothing</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> is</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> done</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> and</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> no</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">destroyed.</span></span></code></pre></div><dl><dt><strong>list</strong> [ <em>SETNAME</em> ] [ <em>OPTIONS</em> ]</dt><dd>List the header data and the entries for the specified set, or for all sets if none is given. The <strong>-resolve</strong> option can be used to force name lookups (which may be slow). When the <strong>-sorted</strong> option is given, the entries are listed/saved sorted (which may be slow). The option <strong>-output</strong> can be used to control the format of the listing: <strong>plain</strong>, <strong>save</strong> or <strong>xml</strong>. (The default is <strong>plain</strong>.) If the option <strong>-name</strong> is specified, just the names of the existing sets are listed. If the option <strong>-terse</strong> is specified, just the set names and headers are listed. The output is printed to stdout, the option <strong>-file</strong> can be used to specify a filename instead of stdout.</dd><dt><strong>save</strong> [ <em>SETNAME</em> ]</dt><dd>Save the given set, or all sets if none is given to stdout in a format that <strong>restore</strong> can read. The option <strong>-file</strong> can be used to specify a filename instead of stdout.</dd><dt><strong>restore</strong></dt><dd>Restore a saved session generated by <strong>save</strong>. The saved session can be fed from stdin or the option <strong>-file</strong> can be used to specify a filename instead of stdin.</dd></dl><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Please</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> note,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> existing</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sets</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> and</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> elements</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> are</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> not</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> erased</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> by</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">restore</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> unless specified so in the restore file. All commands</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">are</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allowed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> except</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> **</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">**</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> **</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">help</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">**</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> **</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">version</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">**</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">interactive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> and</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> **</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">restore</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">**</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> itself.</span></span></code></pre></div><dl><dt><strong>flush</strong> [ <em>SETNAME</em> ]</dt><dd>Flush all entries from the specified set or flush all sets if none is given.</dd><dt><strong>e</strong>, <strong>rename</strong> <em>SETNAME-FROM</em> <em>SETNAME-TO</em></dt><dd>Rename a set. Set identified by <em>SETNAME-TO</em> must not exist.</dd><dt><strong>w</strong>, <strong>swap</strong> <em>SETNAME-FROM</em> <em>SETNAME-TO</em></dt><dd>Swap the content of two sets, or in another words, exchange the name of two sets. The referred sets must exist and compatible type of sets can be swapped only.</dd><dt><strong>help</strong> [ <em>TYPENAME</em> ]</dt><dd>Print help and set type specific help if <em>TYPENAME</em> is specified.</dd><dt><strong>version</strong></dt><dd>Print program version.</dd><dt><strong>-</strong></dt><dd>If a dash is specified as command, then <strong>ipset</strong> enters a simple interactive mode and the commands are read from the standard input. The interactive mode can be finished by entering the pseudo-command <strong>quit</strong>.</dd></dl><h3 id="other-options" tabindex="-1">OTHER OPTIONS <a class="header-anchor" href="#other-options" aria-label="Permalink to &quot;OTHER OPTIONS&quot;">​</a></h3><p>The following additional options can be specified. The long option names cannot be abbreviated.</p><dl><dt><strong>-!</strong>, <strong>-exist</strong></dt><dd>Ignore errors when exactly the same set is to be created or already added entry is added or missing entry is deleted.</dd><dt><strong>-o</strong>, <strong>-output</strong> { <strong>plain</strong> | <strong>save</strong> | <strong>xml</strong> }</dt><dd>Select the output format to the <strong>list</strong> command.</dd><dt><strong>-q</strong>, <strong>-quiet</strong></dt><dd>Suppress any output to stdout and stderr. <strong>ipset</strong> will still exit with error if it cannot continue.</dd><dt><strong>-r</strong>, <strong>-resolve</strong></dt><dd>When listing sets, enforce name lookup. The program will try to display the IP entries resolved to host names which requires <strong>slow</strong> DNS lookups.</dd><dt><strong>-s</strong>, <strong>-sorted</strong></dt><dd>Sorted output. When listing or saving sets, the entries are listed sorted.</dd><dt><strong>-n</strong>, <strong>-name</strong></dt><dd>List just the names of the existing sets, i.e. suppress listing of set headers and members.</dd><dt><strong>-t</strong>, <strong>-terse</strong></dt><dd>List the set names and headers, i.e. suppress listing of set members.</dd><dt><strong>-f</strong>, <strong>-file</strong> <em>filename</em></dt><dd>Specify a filename to print into instead of stdout (<strong>list</strong> or <strong>save</strong> commands) or read from instead of stdin (<strong>restore</strong> command).</dd></dl><h2 id="introduction" tabindex="-1">INTRODUCTION <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;INTRODUCTION&quot;">​</a></h2><p>A set type comprises of the storage method by which the data is stored and the data type(s) which are stored in the set. Therefore the <em>TYPENAME</em> parameter of the <strong>create</strong> command follows the syntax</p><p><em>TYPENAME</em> := <em>method</em>* <em>:</em>* <em>datatype</em>[<strong>,</strong> <em>datatype</em>[<strong>,</strong> <em>datatype</em>]]</p><p>where the current list of the methods are <strong>bitmap</strong>, <strong>hash</strong>, and <strong>list</strong> and the possible data types are <strong>ip</strong>, <strong>net</strong>, <strong>mac</strong>, <strong>port</strong> and <strong>iface</strong>. The dimension of a set is equal to the number of data types in its type name.</p><p>When adding, deleting or testing entries in a set, the same comma separated data syntax must be used for the entry parameter of the commands, i.e</p><blockquote><p>ipset add foo ipaddr,portnum,ipaddr</p></blockquote><p>If host names or service names with dash in the name are used instead of IP addresses or service numbers, then the host name or service name must be enclosed in square brackets. Example:</p><blockquote><p>ipset add foo [test-hostname],[ftp-data]</p></blockquote><p>In the case of host names the DNS resolver is called internally by <strong>ipset</strong> but if it returns multiple IP addresses, only the first one is used.</p><p>The <strong>bitmap</strong> and <strong>list</strong> types use a fixed sized storage. The <strong>hash</strong> types use a hash to store the elements. In order to avoid clashes in the hash, a limited number of chaining, and if that is exhausted, the doubling of the hash size is performed when adding entries by the <strong>ipset</strong> command. When entries added by the <strong>SET</strong> target of <strong>iptables/ip6tables</strong>, then the hash size is fixed and the set won&#39;t be duplicated, even if the new entry cannot be added to the set.</p><h2 id="generic-create-and-add-options" tabindex="-1">GENERIC CREATE AND ADD OPTIONS <a class="header-anchor" href="#generic-create-and-add-options" aria-label="Permalink to &quot;GENERIC CREATE AND ADD OPTIONS&quot;">​</a></h2><h3 id="timeout" tabindex="-1">timeout <a class="header-anchor" href="#timeout" aria-label="Permalink to &quot;timeout&quot;">​</a></h3><p>All set types supports the optional <strong>timeout</strong> parameter when creating a set and adding entries. The value of the <strong>timeout</strong> parameter for the <strong>create</strong> command means the default timeout value (in seconds) for new entries. If a set is created with timeout support, then the same <strong>timeout</strong> option can be used to specify non-default timeout values when adding entries. Zero timeout value means the entry is added permanent to the set. The timeout value of already added elements can be changed by re-adding the element using the <strong>-exist</strong> option. The largest possible timeout value is 2147483 (in seconds). Example:</p><blockquote><p>ipset create test hash:ip timeout 300</p></blockquote><blockquote><p>ipset add test 192.168.0.1 timeout 60</p></blockquote><blockquote><p>ipset -exist add test 192.168.0.1 timeout 600</p></blockquote><p>When listing the set, the number of entries printed in the header might be larger than the listed number of entries for sets with the timeout extensions: the number of entries in the set is updated when elements added/deleted to the set and periodically when the garbage collector evicts the timed out entries.</p><h3 id="counters-packets-bytes" tabindex="-1">counters, packets, bytes <a class="header-anchor" href="#counters-packets-bytes" aria-label="Permalink to &quot;counters, packets, bytes&quot;">​</a></h3><p>All set types support the optional <strong>counters</strong> option when creating a set. If the option is specified then the set is created with packet and byte counters per element support. The packet and byte counters are initialized to zero when the elements are (re-)added to the set, unless the packet and byte counter values are explicitly specified by the <strong>packets</strong> and <strong>bytes</strong> options. An example when an element is added to a set with non-zero counter values:</p><blockquote><p>ipset create foo hash:ip counters</p></blockquote><blockquote><p>ipset add foo 192.168.1.1 packets 42 bytes 1024</p></blockquote><h3 id="comment" tabindex="-1">comment <a class="header-anchor" href="#comment" aria-label="Permalink to &quot;comment&quot;">​</a></h3><p>All set types support the optional <strong>comment</strong> extension. Enabling this extension on an ipset enables you to annotate an ipset entry with an arbitrary string. This string is completely ignored by both the kernel and ipset itself and is purely for providing a convenient means to document the reason for an entry&#39;s existence. Comments must not contain any quotation marks and the usual escape character (\\) has no meaning. For example, the following shell command is illegal:</p><blockquote><p>ipset add foo 1.1.1.1 comment &quot;this comment is \\&quot;bad\\&quot;&quot;</p></blockquote><p>In the above, your shell will of course escape the quotation marks and ipset will see the quote marks in the argument for the comment, which will result in a parse error. If you are writing your own system, you should avoid creating comments containing a quotation mark if you do not want to break &quot;ipset save&quot; and &quot;ipset restore&quot;, nonetheless, the kernel will not stop you from doing so. The following is perfectly acceptable:</p><blockquote><p>ipset create foo hash:ip comment</p></blockquote><blockquote><p>ipset add foo 192.168.1.1/24 comment &quot;allow access to SMB share on \\\\\\\\fileserv\\\\&quot;</p></blockquote><blockquote><p>the above would appear as: &quot;allow access to SMB share on \\\\fileserv\\&quot;</p></blockquote><h3 id="skbinfo-skbmark-skbprio-skbqueue" tabindex="-1">skbinfo, skbmark, skbprio, skbqueue <a class="header-anchor" href="#skbinfo-skbmark-skbprio-skbqueue" aria-label="Permalink to &quot;skbinfo, skbmark, skbprio, skbqueue&quot;">​</a></h3><p>All set types support the optional <strong>skbinfo</strong> extension. This extension allows you to store the metainfo (firewall mark, tc class and hardware queue) with every entry and map it to packets by usage of SET netfilter target with --map-set option. <strong>skbmark</strong> option format: <strong>MARK</strong> or <strong>MARK/MASK</strong>, where <strong>MARK</strong> and <strong>MASK</strong> are 32bit hex numbers with 0x prefix. If only <strong>mark</strong> is specified mask 0xffffffff are used. <strong>skbprio</strong> option has tc class format: <strong>MAJOR:MINOR</strong>, where <strong>major</strong> and <strong>minor</strong> numbers are hex without 0x prefix. <strong>skbqueue</strong> option is just decimal number.</p><blockquote><p>ipset create foo hash:ip skbinfo</p></blockquote><blockquote><p>ipset add foo 192.168.0.1 skbmark 0x1111/0xff00ffff skbprio 1:10 skbqueue 10</p></blockquote><h3 id="hashsize" tabindex="-1">hashsize <a class="header-anchor" href="#hashsize" aria-label="Permalink to &quot;hashsize&quot;">​</a></h3><p>This parameter is valid for the <strong>create</strong> command of all <strong>hash</strong> type sets. It defines the initial hash size for the set, default is 1024. The hash size must be a power of two, the kernel automatically rounds up non power of two hash sizes to the first correct value. Example:</p><blockquote><p>ipset create test hash:ip hashsize 1536</p></blockquote><h3 id="maxelem" tabindex="-1">maxelem <a class="header-anchor" href="#maxelem" aria-label="Permalink to &quot;maxelem&quot;">​</a></h3><p>This parameter is valid for the <strong>create</strong> command of all <strong>hash</strong> type sets. It defines the maximal number of elements which can be stored in the set, default 65536. Example:</p><blockquote><p>ipset create test hash:ip maxelem 2048</p></blockquote><h3 id="bucketsize" tabindex="-1">bucketsize <a class="header-anchor" href="#bucketsize" aria-label="Permalink to &quot;bucketsize&quot;">​</a></h3><p>This parameter is valid for the <strong>create</strong> command of all <strong>hash</strong> type sets. It specifies the maximal number of elements which can be stored in a hash bucket. Possible values are any even number between 2-14 and the default is 14. Setting the value lower forces ipset to create larger hashes which consumes more memory but gives more speed at matching in the set. Example:</p><blockquote><p>ipset create test hash:ip bucketsize 2</p></blockquote><h3 id="family-inet-inet6" tabindex="-1">family { inet | inet6 } <a class="header-anchor" href="#family-inet-inet6" aria-label="Permalink to &quot;family \\{ inet \\| inet6 }&quot;">​</a></h3><p>This parameter is valid for the <strong>create</strong> command of all <strong>hash</strong> type sets except for hash:mac. It defines the protocol family of the IP addresses to be stored in the set. The default is <strong>inet</strong>, i.e IPv4. For the <strong>inet</strong> family one can add or delete multiple entries by specifying a range or a network of IPv4 addresses in the IP address part of the entry:</p><p><em>ipaddr</em> := { <em>ip</em> | <em>fromaddr</em>-<em>toaddr</em> | <em>ip</em>/<em>cidr</em> }</p><p><em>netaddr</em> := { <em>fromaddr</em>-<em>toaddr</em> | <em>ip</em>/<em>cidr</em> }</p><p>Example:</p><blockquote><p>ipset create test hash:ip family inet6</p></blockquote><h3 id="nomatch" tabindex="-1">nomatch <a class="header-anchor" href="#nomatch" aria-label="Permalink to &quot;nomatch&quot;">​</a></h3><p>The <strong>hash</strong> set types which can store <strong>net</strong> type of data (i.e. hash:*net*) support the optional <strong>nomatch</strong> option when adding entries. When matching elements in the set, entries marked as <strong>nomatch</strong> are skipped as if those were not added to the set, which makes possible to build up sets with exceptions. See the example at hash type <strong>hash:net</strong> below.</p><p>When elements are tested by <strong>ipset</strong>, the <strong>nomatch</strong> flags are taken into account. If one wants to test the existence of an element marked with <strong>nomatch</strong> in a set, then the flag must be specified too.</p><h3 id="forceadd" tabindex="-1">forceadd <a class="header-anchor" href="#forceadd" aria-label="Permalink to &quot;forceadd&quot;">​</a></h3><p>All hash set types support the optional <strong>forceadd</strong> parameter when creating a set. When sets created with this option become full the next addition to the set may succeed and evict a random entry from the set.</p><blockquote><p>ipset create foo hash:ip forceadd</p></blockquote><h3 id="wildcard" tabindex="-1">wildcard <a class="header-anchor" href="#wildcard" aria-label="Permalink to &quot;wildcard&quot;">​</a></h3><p>This flag is valid when adding elements to a <strong>hash:net,iface</strong> set. If the flag is set, then prefix matching is used when comparing with this element. For example, an element containing the interface name &quot;eth&quot; will match any name with that prefix.</p><h2 id="set-types" tabindex="-1">SET TYPES <a class="header-anchor" href="#set-types" aria-label="Permalink to &quot;SET TYPES&quot;">​</a></h2><h3 id="bitmap-ip" tabindex="-1">bitmap:ip <a class="header-anchor" href="#bitmap-ip" aria-label="Permalink to &quot;bitmap:ip&quot;">​</a></h3><p>The <strong>bitmap:ip</strong> set type uses a memory range to store either IPv4 host (default) or IPv4 network addresses. A <strong>bitmap:ip</strong> type of set can store up to 65536 entries.</p><p><em>CREATE-OPTIONS</em> := <strong>range</strong> <em>fromip</em>-<em>toip</em>|<em>ip</em>/<em>cidr</em> [ <strong>netmask</strong> <em>cidr</em> ] [ <strong>timeout</strong> <em>value</em> ] [ <strong>counters</strong> ] [ <strong>comment</strong> ] [ <strong>skbinfo</strong> ]</p><p><em>ADD-ENTRY</em> := { <em>ip</em> | <em>fromip</em>-<em>toip</em> | <em>ip</em>/<em>cidr</em> }</p><p><em>ADD-OPTIONS</em> := [ <strong>timeout</strong> <em>value</em> ] [ <strong>packets</strong> <em>value</em> ] [ <strong>bytes</strong> <em>value</em> ] [ <strong>comment</strong> <em>string</em> ] [ <strong>skbmark</strong> <em>value</em> ] [ <strong>skbprio</strong> <em>value</em> ] [ <strong>skbqueue</strong> <em>value</em> ]</p><p><em>DEL-ENTRY</em> := { <em>ip</em> | <em>fromip</em>-<em>toip</em> | <em>ip</em>/<em>cidr</em> }</p><p><em>TEST-ENTRY</em> := <em>ip</em></p><p>Mandatory <strong>create</strong> options:</p><dl><dt><strong>range</strong> <em>fromip</em>-<em>toip</em>|<em>ip</em>/<em>cidr</em></dt><dd>Create the set from the specified inclusive address range expressed in an IPv4 address range or network. The size of the range (in entries) cannot exceed the limit of maximum 65536 elements.</dd></dl><p>Optional <strong>create</strong> options:</p><dl><dt><strong>netmask</strong> <em>cidr</em></dt><dd>When the optional <strong>netmask</strong> parameter specified, network addresses will be stored in the set instead of IP host addresses. The <em>cidr</em> prefix value must be between 1-32. An IP address will be in the set if the network address, which is resulted by masking the address with the specified netmask, can be found in the set.</dd></dl><p>The <strong>bitmap:ip</strong> type supports adding or deleting multiple entries in one command.</p><p>Examples:</p><blockquote><p>ipset create foo bitmap:ip range 192.168.0.0/16</p></blockquote><blockquote><p>ipset add foo 192.168.1/24</p></blockquote><blockquote><p>ipset test foo 192.168.1.1</p></blockquote><h3 id="bitmap-ip-mac" tabindex="-1">bitmap:ip,mac <a class="header-anchor" href="#bitmap-ip-mac" aria-label="Permalink to &quot;bitmap:ip,mac&quot;">​</a></h3><p>The <strong>bitmap:ip,mac</strong> set type uses a memory range to store IPv4 and a MAC address pairs. A <strong>bitmap:ip,mac</strong> type of set can store up to 65536 entries.</p><p><em>CREATE-OPTIONS</em> := <strong>range</strong> <em>fromip</em>-<em>toip</em>|<em>ip</em>/<em>cidr</em> [ <strong>timeout</strong> <em>value</em> ] [ <strong>counters</strong> ] [ <strong>comment</strong> ] [ <strong>skbinfo</strong> ]</p><p><em>ADD-ENTRY</em> := <em>ip</em>[,<em>macaddr</em>]</p><p><em>ADD-OPTIONS</em> := [ <strong>timeout</strong> <em>value</em> ] [ <strong>packets</strong> <em>value</em> ] [ <strong>bytes</strong> <em>value</em> ] [ <strong>comment</strong> <em>string</em> ] [ <strong>skbmark</strong> <em>value</em> ] [ <strong>skbprio</strong> <em>value</em> ] [ <strong>skbqueue</strong> <em>value</em> ]</p><p><em>DEL-ENTRY</em> := <em>ip</em>[,<em>macaddr</em>]</p><p><em>TEST-ENTRY</em> := <em>ip</em>[,<em>macaddr</em>]</p><p>Mandatory options to use when creating a <strong>bitmap:ip,mac</strong> type of set:</p><dl><dt><strong>range</strong> <em>fromip</em>-<em>toip</em>|<em>ip</em>/<em>cidr</em></dt><dd>Create the set from the specified inclusive address range expressed in an IPv4 address range or network. The size of the range cannot exceed the limit of maximum 65536 entries.</dd></dl><p>The <strong>bitmap:ip,mac</strong> type is exceptional in the sense that the MAC part can be left out when adding/deleting/testing entries in the set. If we add an entry without the MAC address specified, then when the first time the entry is matched by the kernel, it will automatically fill out the missing MAC address with the MAC address from the packet. The source MAC address is used if the entry matched due to a <strong>src</strong> parameter of the <strong>set</strong> match, and the destination MAC address is used if available and the entry matched due to a <strong>dst</strong> parameter. If the entry was specified with a timeout value, the timer starts off when the IP and MAC address pair is complete.</p><p>The <strong>bitmap:ip,mac</strong> type of sets require two <strong>src/dst</strong> parameters of the <strong>set</strong> match and <strong>SET</strong> target netfilter kernel modules. For matches on destination MAC addresses, see COMMENTS below.</p><p>Examples:</p><blockquote><p>ipset create foo bitmap:ip,mac range 192.168.0.0/16</p></blockquote><blockquote><p>ipset add foo 192.168.1.1,12:34:56:78:9A:BC</p></blockquote><blockquote><p>ipset test foo 192.168.1.1</p></blockquote><h3 id="bitmap-port" tabindex="-1">bitmap:port <a class="header-anchor" href="#bitmap-port" aria-label="Permalink to &quot;bitmap:port&quot;">​</a></h3><p>The <strong>bitmap:port</strong> set type uses a memory range to store port numbers and such a set can store up to 65536 ports.</p><p><em>CREATE-OPTIONS</em> := <strong>range</strong> <em>fromport</em>-<em>toport [</em> <strong>timeout</strong> <em>value</em> ] [ <strong>counters</strong> ] [ <strong>comment</strong> ] [ <strong>skbinfo</strong> ]</p><p><em>ADD-ENTRY</em> := { <em>[proto:]port</em> | <em>[proto:]fromport</em>-<em>toport</em> }</p><p><em>ADD-OPTIONS</em> := [ <strong>timeout</strong> <em>value</em> ] [ <strong>packets</strong> <em>value</em> ] [ <strong>bytes</strong> <em>value</em> ] [ <strong>comment</strong> <em>string</em> ] [ <strong>skbmark</strong> <em>value</em> ] [ <strong>skbprio</strong> <em>value</em> ] [ <strong>skbqueue</strong> <em>value</em> ]</p><p><em>DEL-ENTRY</em> := { <em>[proto:]port</em> | <em>[proto:]fromport</em>-<em>toport</em> }</p><p><em>TEST-ENTRY</em> := <em>[proto:]port</em></p><p>Mandatory options to use when creating a <strong>bitmap:port</strong> type of set:</p><dl><dt><strong>range</strong> <em>[proto:]fromport</em>-<em>toport</em></dt><dd>Create the set from the specified inclusive port range.</dd></dl><p>The <strong>set</strong> match and <strong>SET</strong> target netfilter kernel modules interpret the stored numbers as TCP or UDP port numbers.</p><p><strong>proto</strong> only needs to be specified if a service name is used and that name does not exist as a TCP service. The protocol is never stored in the set, just the port number of the service.</p><p>Examples:</p><blockquote><p>ipset create foo bitmap:port range 0-1024</p></blockquote><blockquote><p>ipset add foo 80</p></blockquote><blockquote><p>ipset test foo 80</p></blockquote><blockquote><p>ipset del foo udp:[macon-udp]-[tn-tl-w2]</p></blockquote><h3 id="hash-ip" tabindex="-1">hash:ip <a class="header-anchor" href="#hash-ip" aria-label="Permalink to &quot;hash:ip&quot;">​</a></h3><p>The <strong>hash:ip</strong> set type uses a hash to store IP host addresses (default) or network addresses. Zero valued IP address cannot be stored in a <strong>hash:ip</strong> type of set.</p><p><em>CREATE-OPTIONS</em> := [ <strong>family</strong> { <strong>inet</strong> | <strong>inet6</strong> } ] [ <strong>hashsize</strong> <em>value</em> ] [ <strong>maxelem</strong> <em>value</em> ] [ <strong>bucketsize</strong><em>value</em> ] [ <strong>netmask</strong> <em>cidr</em> ] [ <strong>bitmask</strong> <em>mask</em> ] [ <strong>timeout</strong> <em>value</em> ] [ <strong>counters</strong> ] [ <strong>comment</strong> ] [ <strong>skbinfo</strong> ]</p><p><em>ADD-ENTRY</em> := <em>ipaddr</em></p><p><em>ADD-OPTIONS</em> := [ <strong>timeout</strong> <em>value</em> ] [ <strong>packets</strong> <em>value</em> ] [ <strong>bytes</strong> <em>value</em> ] [ <strong>comment</strong> <em>string</em> ] [ <strong>skbmark</strong> <em>value</em> ] [ <strong>skbprio</strong> <em>value</em> ] [ <strong>skbqueue</strong> <em>value</em> ]</p><p><em>DEL-ENTRY</em> := <em>ipaddr</em></p><p><em>TEST-ENTRY</em> := <em>ipaddr</em></p><p>Optional <strong>create</strong> options:</p><dl><dt><strong>netmask</strong> <em>cidr</em></dt><dd>When the optional <strong>netmask</strong> parameter specified, network addresses will be stored in the set instead of IP host addresses. The <em>cidr</em> prefix value must be between 1-32 for IPv4 and between 1-128 for IPv6. An IP address will be in the set if the network address, which is resulted by masking the address with the netmask, can be found in the set. Examples:</dd></dl><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ipset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> foo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hash:ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> netmask</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 30</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ipset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> foo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 192.168.1.0/24</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ipset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> foo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.1.2</span></span></code></pre></div><dl><dt><strong>bitmask</strong> <em>mask</em></dt><dd>This works similar to <strong>netmask</strong> but it will accept any valid IPv4/v6 address. It does not have to be a valid netmask.</dd></dl><h3 id="hash-mac" tabindex="-1">hash:mac <a class="header-anchor" href="#hash-mac" aria-label="Permalink to &quot;hash:mac&quot;">​</a></h3><p>The <strong>hash:mac</strong> set type uses a hash to store MAC addresses. Zero valued MAC addresses cannot be stored in a <strong>hash:mac</strong> type of set. For matches on destination MAC addresses, see COMMENTS below.</p><p><em>CREATE-OPTIONS</em> := [ <strong>hashsize</strong> <em>value</em> ] [ <strong>maxelem</strong> <em>value</em> ] [ <strong>bucketsize</strong> <em>value</em> ] [ <strong>timeout</strong> <em>value</em> ] [ <strong>counters</strong> ] [ <strong>comment</strong> ] [ <strong>skbinfo</strong> ]</p><p><em>ADD-ENTRY</em> := <em>macaddr</em></p><p><em>ADD-OPTIONS</em> := [ <strong>timeout</strong> <em>value</em> ] [ <strong>packets</strong> <em>value</em> ] [ <strong>bytes</strong> <em>value</em> ] [ <strong>comment</strong> <em>string</em> ] [ <strong>skbmark</strong> <em>value</em> ] [ <strong>skbprio</strong> <em>value</em> ] [ <strong>skbqueue</strong> <em>value</em> ]</p><p><em>DEL-ENTRY</em> := <em>macaddr</em></p><p><em>TEST-ENTRY</em> := <em>macaddr</em></p><p>Examples:</p><blockquote><p>ipset create foo hash:mac</p></blockquote><blockquote><p>ipset add foo 01:02:03:04:05:06</p></blockquote><blockquote><p>ipset test foo 01:02:03:04:05:06</p></blockquote><h3 id="hash-ip-mac" tabindex="-1">hash:ip,mac <a class="header-anchor" href="#hash-ip-mac" aria-label="Permalink to &quot;hash:ip,mac&quot;">​</a></h3><p>The <strong>hash:ip,mac</strong> set type uses a hash to store IP and a MAC address pairs. Zero valued MAC addresses cannot be stored in a <strong>hash:ip,mac</strong> type of set. For matches on destination MAC addresses, see COMMENTS below.</p><p><em>CREATE-OPTIONS</em> := [ <strong>family</strong> { <strong>inet</strong> | <strong>inet6</strong> } ] [ <strong>hashsize</strong> <em>value</em> ] [ <strong>maxelem</strong> <em>value</em> ] [ <strong>bucketsize</strong><em>value</em> ] [ <strong>timeout</strong> <em>value</em> ] [ <strong>counters</strong> ] [ <strong>comment</strong> ] [ <strong>skbinfo</strong> ]</p><p><em>ADD-ENTRY</em> := <em>ipaddr</em>,<em>macaddr</em></p><p><em>ADD-OPTIONS</em> := [ <strong>timeout</strong> <em>value</em> ] [ <strong>packets</strong> <em>value</em> ] [ <strong>bytes</strong> <em>value</em> ] [ <strong>comment</strong> <em>string</em> ] [ <strong>skbmark</strong> <em>value</em> ] [ <strong>skbprio</strong> <em>value</em> ] [ <strong>skbqueue</strong> <em>value</em> ]</p><p><em>DEL-ENTRY</em> := <em>ipaddr</em>,<em>macaddr</em></p><p><em>TEST-ENTRY</em> := <em>ipaddr</em>,<em>macaddr</em></p><p>Examples:</p><blockquote><p>ipset create foo hash:ip,mac</p></blockquote><blockquote><p>ipset add foo 1.1.1.1,01:02:03:04:05:06</p></blockquote><blockquote><p>ipset test foo 1.1.1.1,01:02:03:04:05:06</p></blockquote><h3 id="hash-net" tabindex="-1">hash:net <a class="header-anchor" href="#hash-net" aria-label="Permalink to &quot;hash:net&quot;">​</a></h3><p>The <strong>hash:net</strong> set type uses a hash to store different sized IP network addresses. Network address with zero prefix size cannot be stored in this type of sets.</p><p><em>CREATE-OPTIONS</em> := [ <strong>family</strong> { <strong>inet</strong> | <strong>inet6</strong> } ] [ <strong>hashsize</strong> <em>value</em> ] [ <strong>maxelem</strong> <em>value</em> ] [ <strong>bucketsize</strong><em>value</em> ] [ <strong>timeout</strong> <em>value</em> ] [ <strong>counters</strong> ] [ <strong>comment</strong> ] [ <strong>skbinfo</strong> ]</p><p><em>ADD-ENTRY</em> := <em>netaddr</em></p><p><em>ADD-OPTIONS</em> := [ <strong>timeout</strong> <em>value</em> ] [ <strong>nomatch</strong> ] [ <strong>packets</strong> <em>value</em> ] [ <strong>bytes</strong> <em>value</em> ] [ <strong>comment</strong> <em>string</em> ] [ <strong>skbmark</strong> <em>value</em> ] [ <strong>skbprio</strong> <em>value</em> ] [ <strong>skbqueue</strong><em>value</em> ]</p><p><em>DEL-ENTRY</em> := <em>netaddr</em></p><p><em>TEST-ENTRY</em> := <em>netaddr</em></p><p>where <em>netaddr</em> := <em>ip</em>[/<em>cidr</em>]</p><p>When adding/deleting/testing entries, if the cidr prefix parameter is not specified, then the host prefix value is assumed. When adding/deleting entries, the exact element is added/deleted and overlapping elements are not checked by the kernel. When testing entries, if a host address is tested, then the kernel tries to match the host address in the networks added to the set and reports the result accordingly.</p><p>From the <strong>set</strong> netfilter match point of view the searching for a match always starts from the smallest size of netblock (most specific prefix) to the largest one (least specific prefix) added to the set. When adding/deleting IP addresses to the set by the <strong>SET</strong> netfilter target, it will be added/deleted by the most specific prefix which can be found in the set, or by the host prefix value if the set is empty.</p><p>The lookup time grows linearly with the number of the different prefix values added to the set.</p><p>Example:</p><blockquote><p>ipset create foo hash:net</p></blockquote><blockquote><p>ipset add foo 192.168.0.0/24</p></blockquote><blockquote><p>ipset add foo 10.1.0.0/16</p></blockquote><blockquote><p>ipset add foo 192.168.0/24</p></blockquote><blockquote><p>ipset add foo 192.168.0/30 nomatch</p></blockquote><p>When matching the elements in the set above, all IP addresses will match from the networks 192.168.0.0/24, 10.1.0.0/16 and 192.168.0/24 except the ones from 192.168.0/30.</p><h3 id="hash-net-net" tabindex="-1">hash:net,net <a class="header-anchor" href="#hash-net-net" aria-label="Permalink to &quot;hash:net,net&quot;">​</a></h3><p>The <strong>hash:net,net</strong> set type uses a hash to store pairs of different sized IP network addresses. Bear in mind that the first parameter has precedence over the second, so a nomatch entry could be potentially be ineffective if a more specific first parameter existed with a suitable second parameter. Network address with zero prefix size cannot be stored in this type of set.</p><p><em>CREATE-OPTIONS</em> := [ <strong>family</strong> { <strong>inet</strong> | <strong>inet6</strong> } ] [ <strong>hashsize</strong> <em>value</em> ] [ <strong>maxelem</strong> <em>value</em> ] [ <strong>bucketsize</strong><em>value</em> ] [ <strong>netmask</strong> <em>cidr</em> ] [ <strong>bitmask</strong> <em>mask</em> ] [ <strong>timeout</strong> <em>value</em> ] [ <strong>counters</strong> ] [ <strong>comment</strong> ] [ <strong>skbinfo</strong> ]</p><p><em>ADD-ENTRY</em> := <em>netaddr</em>,<em>netaddr</em></p><p><em>ADD-OPTIONS</em> := [ <strong>timeout</strong> <em>value</em> ] [ <strong>nomatch</strong> ] [ <strong>packets</strong> <em>value</em> ] [ <strong>bytes</strong> <em>value</em> ] [ <strong>comment</strong> <em>string</em> ] [ <strong>skbmark</strong> <em>value</em> ] [ <strong>skbprio</strong> <em>value</em> ] [ <strong>skbqueue</strong><em>value</em> ]</p><p><em>DEL-ENTRY</em> := <em>netaddr</em>,<em>netaddr</em></p><p><em>TEST-ENTRY</em> := <em>netaddr</em>,<em>netaddr</em></p><p>where <em>netaddr</em> := <em>ip</em>[/<em>cidr</em>]</p><p>When adding/deleting/testing entries, if the cidr prefix parameter is not specified, then the host prefix value is assumed. When adding/deleting entries, the exact element is added/deleted and overlapping elements are not checked by the kernel. When testing entries, if a host address is tested, then the kernel tries to match the host address in the networks added to the set and reports the result accordingly.</p><p>From the <strong>set</strong> netfilter match point of view the searching for a match always starts from the smallest size of netblock (most specific prefix) to the largest one (least specific prefix) with the first param having precedence. When adding/deleting IP addresses to the set by the <strong>SET</strong> netfilter target, it will be added/deleted by the most specific prefix which can be found in the set, or by the host prefix value if the set is empty.</p><p>The lookup time grows linearly with the number of the different prefix values added to the first parameter of the set. The number of secondary prefixes further increases this as the list of secondary prefixes is traversed per primary prefix.</p><p>Optional <strong>create</strong> options:</p><dl><dt><strong>netmask</strong> <em>cidr</em></dt><dd>When the optional <strong>netmask</strong> parameter specified, network addresses will be stored in the set instead of IP host addresses. The <em>cidr</em> prefix value must be between 1-32 for IPv4 and between 1-128 for IPv6. An IP address will be in the set if the network address, which is resulted by masking the address with the netmask, can be found in the set.</dd><dt><strong>bitmask</strong> <em>mask</em></dt><dd>This works similar to <strong>netmask</strong> but it will accept any valid IPv4/v6 address. It does not have to be a valid netmask.</dd></dl><p>Example:</p><blockquote><p>ipset create foo hash:net,net</p></blockquote><blockquote><p>ipset add foo 192.168.0.0/24,10.0.1.0/24</p></blockquote><blockquote><p>ipset add foo 10.1.0.0/16,10.255.0.0/24</p></blockquote><blockquote><p>ipset add foo 192.168.0/24,192.168.54.0-192.168.54.255</p></blockquote><blockquote><p>ipset add foo 192.168.0/30,192.168.64/30 nomatch</p></blockquote><p>When matching the elements in the set above, all IP addresses will match from the networks 192.168.0.0/24&lt;-&gt;10.0.1.0/24, 10.1.0.0/16&lt;-&gt;10.255.0.0/24 and 192.168.0/24&lt;-&gt;192.168.54.0/24 except the ones from 192.168.0/30&lt;-&gt;192.168.64/30.</p><h3 id="hash-ip-port" tabindex="-1">hash:ip,port <a class="header-anchor" href="#hash-ip-port" aria-label="Permalink to &quot;hash:ip,port&quot;">​</a></h3><p>The <strong>hash:ip,port</strong> set type uses a hash to store IP address and port number pairs. The port number is interpreted together with a protocol (default TCP) and zero protocol number cannot be used.</p><p><em>CREATE-OPTIONS</em> := [ <strong>family</strong> { <strong>inet</strong> | <strong>inet6</strong> } ] [ <strong>hashsize</strong> <em>value</em> ] [ <strong>maxelem</strong> <em>value</em> ] [ <strong>bucketsize</strong><em>value</em> ] [ <strong>netmask</strong> <em>cidr</em> ] [ <strong>bitmask</strong> <em>mask</em> ] [ <strong>timeout</strong> <em>value</em> ] [ <strong>counters</strong> ] [ <strong>comment</strong> ] [ <strong>skbinfo</strong> ]</p><p><em>ADD-ENTRY</em> := <em>ipaddr</em>,[<em>proto</em>:]<em>port</em></p><p><em>ADD-OPTIONS</em> := [ <strong>timeout</strong> <em>value</em> ] [ <strong>packets</strong> <em>value</em> ] [ <strong>bytes</strong> <em>value</em> ] [ <strong>comment</strong> <em>string</em> ] [ <strong>skbmark</strong> <em>value</em> ] [ <strong>skbprio</strong> <em>value</em> ] [ <strong>skbqueue</strong> <em>value</em> ]</p><p><em>DEL-ENTRY</em> := <em>ipaddr</em>,[<em>proto</em>:]<em>port</em></p><p><em>TEST-ENTRY</em> := <em>ipaddr</em>,[<em>proto</em>:]<em>port</em></p><p>The [<em>proto</em>:]<em>port</em> part of the elements may be expressed in the following forms, where the range variations are valid when adding or deleting entries:</p><dl><dt><em>portname[-portname]</em></dt><dd>TCP port or range of ports expressed in TCP portname identifiers from /etc/services</dd><dt><em>portnumber[-portnumber]</em></dt><dd>TCP port or range of ports expressed in TCP port numbers</dd><dt><strong>tcp</strong>|<strong>sctp</strong>|<strong>udp</strong>|<strong>udplite</strong>:<em>portname</em>|<em>portnumber</em>[-<em>portname</em>|<em>portnumber</em>]</dt><dd>TCP, SCTP, UDP or UDPLITE port or port range expressed in port name(s) or port number(s)</dd><dt><strong>icmp</strong>:<em>codename</em>|<em>type</em>/<em>code</em></dt><dd>ICMP codename or type/code. The supported ICMP codename identifiers can always be listed by the help command.</dd><dt><strong>icmpv6</strong>:<em>codename</em>|<em>type</em>/<em>code</em></dt><dd>ICMPv6 codename or type/code. The supported ICMPv6 codename identifiers can always be listed by the help command.</dd><dt><em>proto</em>:0</dt><dd>All other protocols, as an identifier from /etc/protocols or number. The pseudo port number must be zero.</dd></dl><p>The <strong>hash:ip,port</strong> type of sets require two <strong>src</strong>/<strong>dst</strong> parameters of the <strong>set</strong> match and <strong>SET</strong> target kernel modules.</p><p>Optional <strong>create</strong> options:</p><dl><dt><strong>netmask</strong> <em>cidr</em></dt><dd>When the optional <strong>netmask</strong> parameter specified, network addresses will be stored in the set instead of IP host addresses. The <em>cidr</em> prefix value must be between 1-32 for IPv4 and between 1-128 for IPv6. An IP address will be in the set if the network address, which is resulted by masking the address with the netmask, can be found in the set.</dd><dt><strong>bitmask</strong> <em>mask</em></dt><dd>This works similar to <strong>netmask</strong> but it will accept any valid IPv4/v6 address. It does not have to be a valid netmask.</dd></dl><p>Examples:</p><blockquote><p>ipset create foo hash:ip,port</p></blockquote><blockquote><p>ipset add foo 192.168.1.0/24,80-82</p></blockquote><blockquote><p>ipset add foo 192.168.1.1,udp:53</p></blockquote><blockquote><p>ipset add foo 192.168.1.1,vrrp:0</p></blockquote><blockquote><p>ipset test foo 192.168.1.1,80</p></blockquote><h3 id="hash-net-port" tabindex="-1">hash:net,port <a class="header-anchor" href="#hash-net-port" aria-label="Permalink to &quot;hash:net,port&quot;">​</a></h3><p>The <strong>hash:net,port</strong> set type uses a hash to store different sized IP network address and port pairs. The port number is interpreted together with a protocol (default TCP) and zero protocol number cannot be used. Network address with zero prefix size is not accepted either.</p><p><em>CREATE-OPTIONS</em> := [ <strong>family</strong> { <strong>inet</strong> | <strong>inet6</strong> } ] [ <strong>hashsize</strong> <em>value</em> ] [ <strong>maxelem</strong> <em>value</em> ] [ <strong>bucketsize</strong><em>value</em> ] [ <strong>timeout</strong> <em>value</em> ] [ <strong>counters</strong> ] [ <strong>comment</strong> ] [ <strong>skbinfo</strong> ]</p><p><em>ADD-ENTRY</em> := <em>netaddr</em>,[<em>proto</em>:]<em>port</em></p><p><em>ADD-OPTIONS</em> := [ <strong>timeout</strong> <em>value</em> ] [ <strong>nomatch</strong> ] [ <strong>packets</strong> <em>value</em> ] [ <strong>bytes</strong> <em>value</em> ] [ <strong>comment</strong> <em>string</em> ] [ <strong>skbmark</strong> <em>value</em> ] [ <strong>skbprio</strong> <em>value</em> ] [ <strong>skbqueue</strong><em>value</em> ]</p><p><em>DEL-ENTRY</em> := <em>netaddr</em>,[<em>proto</em>:]<em>port</em></p><p><em>TEST-ENTRY</em> := <em>netaddr</em>,[<em>proto</em>:]<em>port</em></p><p>where <em>netaddr</em> := <em>ip</em>[/<em>cidr</em>]</p><p>For the <em>netaddr</em> part of the elements see the description at the <strong>hash:net</strong> set type. For the [<em>proto</em>:]<em>port</em> part of the elements see the description at the <strong>hash:ip,port</strong> set type.</p><p>When adding/deleting/testing entries, if the cidr prefix parameter is not specified, then the host prefix value is assumed. When adding/deleting entries, the exact element is added/deleted and overlapping elements are not checked by the kernel. When testing entries, if a host address is tested, then the kernel tries to match the host address in the networks added to the set and reports the result accordingly.</p><p>From the <strong>set</strong> netfilter match point of view the searching for a match always starts from the smallest size of netblock (most specific prefix) to the largest one (least specific prefix) added to the set. When adding/deleting IP addresses to the set by the <strong>SET</strong> netfilter target, it will be added/deleted by the most specific prefix which can be found in the set, or by the host prefix value if the set is empty.</p><p>The lookup time grows linearly with the number of the different prefix values added to the set.</p><p>Examples:</p><blockquote><p>ipset create foo hash:net,port</p></blockquote><blockquote><p>ipset add foo 192.168.0/24,25</p></blockquote><blockquote><p>ipset add foo 10.1.0.0/16,80</p></blockquote><blockquote><p>ipset test foo 192.168.0/24,25</p></blockquote><h3 id="hash-ip-port-ip" tabindex="-1">hash:ip,port,ip <a class="header-anchor" href="#hash-ip-port-ip" aria-label="Permalink to &quot;hash:ip,port,ip&quot;">​</a></h3><p>The <strong>hash:ip,port,ip</strong> set type uses a hash to store IP address, port number and a second IP address triples. The port number is interpreted together with a protocol (default TCP) and zero protocol number cannot be used.</p><p><em>CREATE-OPTIONS</em> := [ <strong>family</strong> { <strong>inet</strong> | <strong>inet6</strong> } ] [ <strong>hashsize</strong> <em>value</em> ] [ <strong>maxelem</strong> <em>value</em> ] [ <strong>bucketsize</strong><em>value</em> ] [ <strong>timeout</strong> <em>value</em> ] [ <strong>counters</strong> ] [ <strong>comment</strong> ] [ <strong>skbinfo</strong> ]</p><p><em>ADD-ENTRY</em> := <em>ipaddr</em>,[<em>proto</em>:]<em>port</em>,<em>ip</em></p><p><em>ADD-OPTIONS</em> := [ <strong>timeout</strong> <em>value</em> ] [ <strong>packets</strong> <em>value</em> ] [ <strong>bytes</strong> <em>value</em> ] [ <strong>comment</strong> <em>string</em> ] [ <strong>skbmark</strong> <em>value</em> ] [ <strong>skbprio</strong> <em>value</em> ] [ <strong>skbqueue</strong> <em>value</em> ]</p><p><em>DEL-ENTRY</em> := <em>ipaddr</em>,[<em>proto</em>:]<em>port</em>,<em>ip</em></p><p><em>TEST-ENTRY</em> := <em>ipaddr</em>,[<em>proto</em>:]<em>port</em>,<em>ip</em></p><p>For the first <em>ipaddr</em> and [<em>proto</em>:]<em>port</em> parts of the elements see the descriptions at the <strong>hash:ip,port</strong> set type.</p><p>The <strong>hash:ip,port,ip</strong> type of sets require three <strong>src</strong>/<strong>dst</strong> parameters of the <strong>set</strong> match and <strong>SET</strong> target kernel modules.</p><p>Examples:</p><blockquote><p>ipset create foo hash:ip,port,ip</p></blockquote><blockquote><p>ipset add foo 192.168.1.1,80,10.0.0.1</p></blockquote><blockquote><p>ipset test foo 192.168.1.1,udp:53,10.0.0.1</p></blockquote><h3 id="hash-ip-port-net" tabindex="-1">hash:ip,port,net <a class="header-anchor" href="#hash-ip-port-net" aria-label="Permalink to &quot;hash:ip,port,net&quot;">​</a></h3><p>The <strong>hash:ip,port,net</strong> set type uses a hash to store IP address, port number and IP network address triples. The port number is interpreted together with a protocol (default TCP) and zero protocol number cannot be used. Network address with zero prefix size cannot be stored either.</p><p><em>CREATE-OPTIONS</em> := [ <strong>family</strong> { <strong>inet</strong> | <strong>inet6</strong> } ] [ <strong>hashsize</strong> <em>value</em> ] [ <strong>maxelem</strong> <em>value</em> ] [ <strong>bucketsize</strong><em>value</em> ] [ <strong>timeout</strong> <em>value</em> ] [ <strong>counters</strong> ] [ <strong>comment</strong> ] [ <strong>skbinfo</strong> ]</p><p><em>ADD-ENTRY</em> := <em>ipaddr</em>,[<em>proto</em>:]<em>port</em>,<em>netaddr</em></p><p><em>ADD-OPTIONS</em> := [ <strong>timeout</strong> <em>value</em> ] [ <strong>nomatch</strong> ] [ <strong>packets</strong> <em>value</em> ] [ <strong>bytes</strong> <em>value</em> ] [ <strong>comment</strong> <em>string</em> ] [ <strong>skbmark</strong> <em>value</em> ] [ <strong>skbprio</strong> <em>value</em> ] [ <strong>skbqueue</strong><em>value</em> ]</p><p><em>DEL-ENTRY</em> := <em>ipaddr</em>,[<em>proto</em>:]<em>port</em>,<em>netaddr</em></p><p><em>TEST-ENTRY</em> := <em>ipaddr</em>,[<em>proto</em>:]<em>port</em>,<em>netaddr</em></p><p>where <em>netaddr</em> := <em>ip</em>[/<em>cidr</em>]</p><p>For the <em>ipaddr</em> and [<em>proto</em>:]<em>port</em> parts of the elements see the descriptions at the <strong>hash:ip,port</strong> set type. For the <em>netaddr</em> part of the elements see the description at the <strong>hash:net</strong> set type.</p><p>From the <strong>set</strong> netfilter match point of view the searching for a match always starts from the smallest size of netblock (most specific cidr) to the largest one (least specific cidr) added to the set. When adding/deleting triples to the set by the <strong>SET</strong> netfilter target, it will be added/deleted by the most specific cidr which can be found in the set, or by the host cidr value if the set is empty.</p><p>The lookup time grows linearly with the number of the different <em>cidr</em> values added to the set.</p><p>The <strong>hash:ip,port,net</strong> type of sets require three <strong>src</strong>/<strong>dst</strong> parameters of the <strong>set</strong> match and <strong>SET</strong> target kernel modules.</p><p>Examples:</p><blockquote><p>ipset create foo hash:ip,port,net</p></blockquote><blockquote><p>ipset add foo 192.168.1,80,10.0.0/24</p></blockquote><blockquote><p>ipset add foo 192.168.2,25,10.1.0.0/16</p></blockquote><blockquote><p>ipset test foo 192.168.1,80.10.0.0/24</p></blockquote><h3 id="hash-ip-mark" tabindex="-1">hash:ip,mark <a class="header-anchor" href="#hash-ip-mark" aria-label="Permalink to &quot;hash:ip,mark&quot;">​</a></h3><p>The <strong>hash:ip,mark</strong> set type uses a hash to store IP address and packet mark pairs.</p><p><em>CREATE-OPTIONS</em> := [ <strong>family</strong> { <strong>inet</strong> | <strong>inet6</strong> } ] [ <strong>markmask</strong> <em>value</em> ] [ <strong>hashsize</strong> <em>value</em> ] [ <strong>maxelem</strong><em>value</em> ] [ <strong>bucketsize</strong> <em>value</em> ] [ <strong>timeout</strong> <em>value</em> ] [ <strong>counters</strong> ] [ <strong>comment</strong> ] [ <strong>skbinfo</strong> ]</p><p><em>ADD-ENTRY</em> := <em>ipaddr</em>,<em>mark</em></p><p><em>ADD-OPTIONS</em> := [ <strong>timeout</strong> <em>value</em> ] [ <strong>packets</strong> <em>value</em> ] [ <strong>bytes</strong> <em>value</em> ] [ <strong>comment</strong> <em>string</em> ] [ <strong>skbmark</strong> <em>value</em> ] [ <strong>skbprio</strong> <em>value</em> ] [ <strong>skbqueue</strong> <em>value</em> ]</p><p><em>DEL-ENTRY</em> := <em>ipaddr</em>,<em>mark</em></p><p><em>TEST-ENTRY</em> := <em>ipaddr</em>,<em>mark</em></p><p>Optional <strong>create</strong> options:</p><dl><dt><strong>markmask</strong> <em>value</em></dt><dd>Allows you to set bits you are interested in the packet mark. This values is then used to perform bitwise AND operation for every mark added. markmask can be any value between 1 and 4294967295, by default all 32 bits are set.</dd></dl><p>The <em>mark</em> can be any value between 0 and 4294967295.</p><p>The <strong>hash:ip,mark</strong> type of sets require two <strong>src</strong>/<strong>dst</strong> parameters of the <strong>set</strong> match and <strong>SET</strong> target kernel modules.</p><p>Examples:</p><blockquote><p>ipset create foo hash:ip,mark</p></blockquote><blockquote><p>ipset add foo 192.168.1.0/24,555</p></blockquote><blockquote><p>ipset add foo 192.168.1.1,0x63</p></blockquote><blockquote><p>ipset add foo 192.168.1.1,111236</p></blockquote><h3 id="hash-net-port-net" tabindex="-1">hash:net,port,net <a class="header-anchor" href="#hash-net-port-net" aria-label="Permalink to &quot;hash:net,port,net&quot;">​</a></h3><p>The <strong>hash:net,port,net</strong> set type behaves similarly to hash:ip,port,net but accepts a cidr value for both the first and last parameter. Either subnet is permitted to be a /0 should you wish to match port between all destinations.</p><p><em>CREATE-OPTIONS</em> := [ <strong>family</strong> { <strong>inet</strong> | <strong>inet6</strong> } ] [ <strong>hashsize</strong> <em>value</em> ] [ <strong>maxelem</strong> <em>value</em> ] [ <strong>bucketsize</strong><em>value</em> ] [ <strong>timeout</strong> <em>value</em> ] [ <strong>counters</strong> ] [ <strong>comment</strong> ] [ <strong>skbinfo</strong> ]</p><p><em>ADD-ENTRY</em> := <em>netaddr</em>,[<em>proto</em>:]<em>port</em>,<em>netaddr</em></p><p><em>ADD-OPTIONS</em> := [ <strong>timeout</strong> <em>value</em> ] [ <strong>nomatch</strong> ] [ <strong>packets</strong> <em>value</em> ] [ <strong>bytes</strong> <em>value</em> ] [ <strong>comment</strong> <em>string</em> ] [ <strong>skbmark</strong> <em>value</em> ] [ <strong>skbprio</strong> <em>value</em> ] [ <strong>skbqueue</strong><em>value</em> ]</p><p><em>DEL-ENTRY</em> := <em>netaddr</em>,[<em>proto</em>:]<em>port</em>,<em>netaddr</em></p><p><em>TEST-ENTRY</em> := <em>netaddr</em>,[<em>proto</em>:]<em>port</em>,<em>netaddr</em></p><p>where <em>netaddr</em> := <em>ip</em>[/<em>cidr</em>]</p><p>For the [<em>proto</em>:]<em>port</em> part of the elements see the description at the <strong>hash:ip,port</strong> set type. For the <em>netaddr</em> part of the elements see the description at the <strong>hash:net</strong> set type.</p><p>From the <strong>set</strong> netfilter match point of view the searching for a match always starts from the smallest size of netblock (most specific cidr) to the largest one (least specific cidr) added to the set. When adding/deleting triples to the set by the <strong>SET</strong> netfilter target, it will be added/deleted by the most specific cidr which can be found in the set, or by the host cidr value if the set is empty. The first subnet has precedence when performing the most-specific lookup, just as for hash:net,net</p><p>The lookup time grows linearly with the number of the different <em>cidr</em> values added to the set and by the number of secondary <em>cidr</em> values per primary.</p><p>The <strong>hash:net,port,net</strong> type of sets require three <strong>src</strong>/<strong>dst</strong> parameters of the <strong>set</strong> match and <strong>SET</strong> target kernel modules.</p><p>Examples:</p><blockquote><p>ipset create foo hash:net,port,net</p></blockquote><blockquote><p>ipset add foo 192.168.1.0/24,0,10.0.0/24</p></blockquote><blockquote><p>ipset add foo 192.168.2.0/24,25,10.1.0.0/16</p></blockquote><blockquote><p>ipset test foo 192.168.1.1,80,10.0.0.1</p></blockquote><h3 id="hash-net-iface" tabindex="-1">hash:net,iface <a class="header-anchor" href="#hash-net-iface" aria-label="Permalink to &quot;hash:net,iface&quot;">​</a></h3><p>The <strong>hash:net,iface</strong> set type uses a hash to store different sized IP network address and interface name pairs.</p><p><em>CREATE-OPTIONS</em> := [ <strong>family</strong> { <strong>inet</strong> | <strong>inet6</strong> } ] [ <strong>hashsize</strong> <em>value</em> ] [ <strong>maxelem</strong> <em>value</em> ] [ <strong>bucketsize</strong><em>value</em> ] [ <strong>timeout</strong> <em>value</em> ] [ <strong>counters</strong> ] [ <strong>comment</strong> ] [ <strong>skbinfo</strong> ]</p><p><em>ADD-ENTRY</em> := <em>netaddr</em>,[<strong>physdev</strong>:]<em>iface</em></p><p><em>ADD-OPTIONS</em> := [ <strong>timeout</strong> <em>value</em> ] [ <strong>nomatch</strong> ] [ <strong>packets</strong> <em>value</em> ] [ <strong>bytes</strong> <em>value</em> ] [ <strong>comment</strong> <em>string</em> ] [ <strong>skbmark</strong> <em>value</em> ] [ <strong>skbprio</strong> <em>value</em> ] [ <strong>skbqueue</strong><em>value</em> ] [ <strong>wildcard</strong> ]</p><p><em>DEL-ENTRY</em> := <em>netaddr</em>,[<strong>physdev</strong>:]<em>iface</em></p><p><em>TEST-ENTRY</em> := <em>netaddr</em>,[<strong>physdev</strong>:]<em>iface</em></p><p>where <em>netaddr</em> := <em>ip</em>[/<em>cidr</em>]</p><p>For the <em>netaddr</em> part of the elements see the description at the <strong>hash:net</strong> set type.</p><p>When adding/deleting/testing entries, if the cidr prefix parameter is not specified, then the host prefix value is assumed. When adding/deleting entries, the exact element is added/deleted and overlapping elements are not checked by the kernel. When testing entries, if a host address is tested, then the kernel tries to match the host address in the networks added to the set and reports the result accordingly.</p><p>From the <strong>set</strong> netfilter match point of view the searching for a match always starts from the smallest size of netblock (most specific prefix) to the largest one (least specific prefix) added to the set. When adding/deleting IP addresses to the set by the <strong>SET</strong> netfilter target, it will be added/deleted by the most specific prefix which can be found in the set, or by the host prefix value if the set is empty.</p><p>The second direction parameter of the <strong>set</strong> match and <strong>SET</strong> target modules corresponds to the incoming/outgoing interface: <strong>src</strong> to the incoming one (similar to the <strong>-i</strong> flag of iptables), while <strong>dst</strong> to the outgoing one (similar to the <strong>-o</strong> flag of iptables). When the interface is flagged with <strong>physdev:</strong>, the interface is interpreted as the incoming/outgoing bridge port.</p><p>The lookup time grows linearly with the number of the different prefix values added to the set.</p><p>The internal restriction of the <strong>hash:net,iface</strong> set type is that the same network prefix cannot be stored with more than 64 different interfaces in a single set.</p><p>Examples:</p><blockquote><p>ipset create foo hash:net,iface</p></blockquote><blockquote><p>ipset add foo 192.168.0/24,eth0</p></blockquote><blockquote><p>ipset add foo 10.1.0.0/16,eth1</p></blockquote><blockquote><p>ipset test foo 192.168.0/24,eth0</p></blockquote><h3 id="list-set" tabindex="-1">list:set <a class="header-anchor" href="#list-set" aria-label="Permalink to &quot;list:set&quot;">​</a></h3><p>The <strong>list:set</strong> type uses a simple list in which you can store set names.</p><p><em>CREATE-OPTIONS</em> := [ <strong>size</strong> <em>value</em> ] [ <strong>timeout</strong> <em>value</em> ] [ <strong>counters</strong> ] [ <strong>comment</strong> ] [ <strong>skbinfo</strong> ]</p><p><em>ADD-ENTRY</em> := <em>setname</em> [ { <strong>before</strong> | <strong>after</strong> } <em>setname</em> ]</p><p><em>ADD-OPTIONS</em> := [ <strong>timeout</strong> <em>value</em> ] [ <strong>packets</strong> <em>value</em> ] [ <strong>bytes</strong> <em>value</em> ] [ <strong>comment</strong> <em>string</em> ] [ <strong>skbmark</strong> <em>value</em> ] [ <strong>skbprio</strong> <em>value</em> ] [ <strong>skbqueue</strong> <em>value</em> ]</p><p><em>DEL-ENTRY</em> := <em>setname</em> [ { <strong>before</strong> | <strong>after</strong> } <em>setname</em> ]</p><p><em>TEST-ENTRY</em> := <em>setname</em> [ { <strong>before</strong> | <strong>after</strong> } <em>setname</em> ]</p><p>Optional <strong>create</strong> options:</p><dl><dt><strong>size</strong> <em>value</em></dt><dd>The size of the list, the default is 8. The parameter is ignored since ipset version 6.24.</dd></dl><p>By the <strong>ipset</strong> command you can add, delete and test set names in a <strong>list:set</strong> type of set.</p><p>By the <strong>set</strong> match or <strong>SET</strong> target of netfilter you can test, add or delete entries in the sets added to the <strong>list:set</strong> type of set. The match will try to find a matching entry in the sets and the target will try to add an entry to the first set to which it can be added. The number of direction options of the match and target are important: sets which require more parameters than specified are skipped, while sets with equal or less parameters are checked, elements added/deleted. For example if <em>a</em> and <em>b</em> are <strong>list:set</strong> type of sets then in the command</p><blockquote><p>iptables -m set --match-set a src,dst -j SET --add-set b src,dst</p></blockquote><p>the match and target will skip any set in <em>a</em> and <em>b</em> which stores data triples, but will match all sets with single or double data storage in <em>a</em> set and stop matching at the first successful set, and add src to the first single or src,dst to the first double data storage set in <em>b</em> to which the entry can be added. You can imagine a <strong>list:set</strong> type of set as an ordered union of the set elements.</p><p>Please note: by the <strong>ipset</strong> command you can add, delete and <strong>test</strong> the setnames in a <strong>list:set</strong> type of set, and <strong>not</strong> the presence of a set&#39;s member (such as an IP address).</p><h2 id="general-restrictions" tabindex="-1">GENERAL RESTRICTIONS <a class="header-anchor" href="#general-restrictions" aria-label="Permalink to &quot;GENERAL RESTRICTIONS&quot;">​</a></h2><p>Zero valued set entries cannot be used with hash methods. Zero protocol value with ports cannot be used.</p><h2 id="comments" tabindex="-1">COMMENTS <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;COMMENTS&quot;">​</a></h2><p>If you want to store same size subnets from a given network (say /24 blocks from a /8 network), use the <strong>bitmap:ip</strong> set type. If you want to store random same size networks (say random /24 blocks), use the <strong>hash:ip</strong> set type. If you have got random size of netblocks, use <strong>hash:net</strong>.</p><p>Matching on destination MAC addresses using the <strong>dst</strong> parameter of the <strong>set</strong> match netfilter kernel modules will only work if the destination MAC address is available in the packet at the given processing stage, that is, it only applies for incoming packets in the <strong>PREROUTING</strong>, <strong>INPUT</strong> and <strong>FORWARD</strong> chains, against the MAC address as originally found in the received packet (typically, one of the MAC addresses of the local host). This is <strong>not</strong> the destination MAC address a destination IP address resolves to, after routing. If the MAC address is not available (e.g. in the <strong>OUTPUT</strong> chain), the packet will simply not match.</p><p>Backward compatibility is maintained and old <strong>ipset</strong> syntax is still supported.</p><p>The <strong>iptree</strong> and <strong>iptreemap</strong> set types are removed: if you refer to them, they are automatically replaced by <strong>hash:ip</strong> type of sets.</p><h2 id="diagnostics" tabindex="-1">DIAGNOSTICS <a class="header-anchor" href="#diagnostics" aria-label="Permalink to &quot;DIAGNOSTICS&quot;">​</a></h2><p>Various error messages are printed to standard error. The exit code is 0 for correct functioning.</p><h2 id="bugs" tabindex="-1">BUGS <a class="header-anchor" href="#bugs" aria-label="Permalink to &quot;BUGS&quot;">​</a></h2><p>Bugs? No, just funny features. 😃 OK, just kidding...</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>iptables</strong>(8), <strong>ip6tables</strong>(8) <strong>iptables-extensions</strong>(8)</p><h2 id="authors" tabindex="-1">AUTHORS <a class="header-anchor" href="#authors" aria-label="Permalink to &quot;AUTHORS&quot;">​</a></h2><p>Jozsef Kadlecsik wrote ipset, which is based on ippool by Joakim Axelsson, Patrick Schaaf and Martin Josefsson. <br> Sven Wegener wrote the iptreemap type.</p><h2 id="last-remark" tabindex="-1">LAST REMARK <a class="header-anchor" href="#last-remark" aria-label="Permalink to &quot;LAST REMARK&quot;">​</a></h2><p><strong>I stand on the shoulders of giants.</strong></p>`,357))])}const k=s(m,[["render",d]]);export{f as __pageData,k as default};
